function filteredJobs(){
 const q=jobQuery.trim().toLowerCase();
 return q?jobs.filter(job=>String(job.title||'').toLowerCase().includes(q)):jobs;
}
function jobPriorityLabel(value){
 const v=String(value||'standard');
 if(v==='hot')return 'Hot';if(v==='priority')return 'High';if(v==='hold')return 'On Hold';
 const n=Number(value);if(Number.isFinite(n)&&n>=8)return 'High';if(Number.isFinite(n)&&n>=4)return 'Standard';
 return 'Standard';
}
function jobReadinessLabel(value){
 return value==='ready'?'Ready to Match':value==='needs_review'?'Review Items':'Not Ready';
}
function drawJobList(){
 const list=$('#jobList');if(!list)return;
 const rows=filteredJobs();
 list.innerHTML=rows.length?rows.map(job=>'<button class="job-card '+(activeJob?.id===job.id?'active':'')+'" data-job="'+esc(job.id)+'"><div class="match-job-row"><div><strong>'+esc(job.title)+'</strong><small>'+esc([job.customer_name,job.division,[job.city,job.state].filter(Boolean).join(', ')].filter(Boolean).join(' · '))+'</small></div><span class="job-readiness-pill '+esc(job.match_readiness||'limited_data')+'">'+esc(jobReadinessLabel(job.match_readiness))+'</span></div><small>'+esc(jobPriorityLabel(job.operational?.job_priority||job.priority))+' priority · '+esc(job.strong_match_count||0)+' strong · '+esc(job.good_match_count||0)+' good'+(job.start_date?' · Starts '+esc(job.start_date):' · Start pending')+'</small></button>').join(''):'<div class="panel empty">No jobs match this view.</div>';
 const more=$('#moreJobs');if(more)more.hidden=!nextJob;
}
async function loadJobs(append=false){
 const result=await call('/jobs?limit=50'+(append&&nextJob?'&after='+encodeURIComponent(nextJob):''));
 jobs=append?[...jobs,...result.items]:result.items;nextJob=result.next_cursor;drawJobList();
 const count=$('#jobCount');if(count)count.textContent=jobs.length;
}
