async function loadIntakeBatch(id){
 const result=await call('/job-intake/batches/'+encodeURIComponent(id)+'/items?limit=200');
 activeIntake=result.batch;activeIntakeItems=result.items||[];
 const detail=$('#intakeDetail');if(!detail)return;
 const rows=activeIntakeItems;
 const jdState=item=>{
   const source=String(item.normalized_job?.description||'').trim();
   const ai=(item.ai_suggestions||[]).find(x=>x&&x.type==='jd_draft');
   if(item.status==='approved')return 'Approved JD';
   if(source.length>=120)return 'Source JD';
   if(ai?.provenance==='medlivo_standard')return 'Medlivo Standard Ready';
   if(ai)return 'AI Draft Ready';
   return 'AI Draft Needed';
 };
 const draftable=rows.filter(item=>!['duplicate','approved','rejected','synced','failed'].includes(item.status)).length;
 detail.innerHTML='<div class="detail-heading"><div><p class="eyebrow">UPLOAD REVIEW</p><h2>'+esc(activeIntake.customer_name)+'</h2><p class="muted small">'+esc(activeIntake.source_filename)+' · '+esc(activeIntake.division)+'</p></div><div class="admin-actions">'+(draftable?'<button class="button primary" data-prepare-standard-jds>Prepare All JDs</button>':'')+'<span class="pill">'+esc(activeIntake.status)+'</span></div></div>'+
 '<div class="manager-metrics"><article class="metric-card"><b>'+esc(activeIntake.ready_count)+'</b><span>Ready</span></article><article class="metric-card attention"><b>'+esc(activeIntake.review_count)+'</b><span>Needs review</span></article><article class="metric-card"><b>'+esc(activeIntake.duplicate_count)+'</b><span>Duplicates</span></article><article class="metric-card"><b>'+esc(activeIntake.row_count)+'</b><span>Total rows</span></article></div>'+
 '<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Row</th><th>Status</th><th>Position</th><th>Facility / Location</th><th>Dates / Hours</th><th>JD</th><th></th></tr></thead><tbody>'+
 (rows.length?rows.map(item=>{const j=item.normalized_job||{},errs=item.validation_errors||[];return '<tr><td>'+esc(item.row_number)+'</td><td><span class="status-chip '+(item.status==='review'||item.status==='duplicate'?'off':'')+'">'+esc(item.status)+'</span></td><td><strong>'+esc(j.title||'Needs mapping')+'</strong><small>'+esc(j.requisition_id||'')+'</small></td><td>'+esc(j.facility||'')+'<small>'+esc([j.city,j.state].filter(Boolean).join(', '))+'</small></td><td>'+esc([j.start_date,j.end_date].filter(Boolean).join(' → '))+'<small>'+(j.hours_per_week!=null?esc(j.hours_per_week)+' hrs/week':'')+'</small></td><td><strong>'+esc(jdState(item))+'</strong><small>'+esc(errs.map(e=>e.message).join('; ')||(item.status==='duplicate'?'Possible duplicate row':''))+'</small></td><td>'+(item.status==='duplicate'?'<span class="muted small">Resolve duplicate first</span>':item.job_publication_id?'<button class="button compact" data-open-intake-publication="'+esc(item.job_publication_id)+'">Open Job Approval</button>':'<button class="button compact" data-intake-item-review="'+esc(item.id)+'">Review JD</button>')+'</td></tr>';}).join(''):'<tr><td colspan="7">No rows were processed.</td></tr>')+
 '</tbody></table></div><div id="intakeItemReview"></div>';
 if(activeIntakeItem&&rows.some(x=>x.id===activeIntakeItem.id))renderIntakeItemReview(activeIntakeItem.id);
}
function intakeAiDraft(item){return (item.ai_suggestions||[]).filter(x=>x&&x.type==='jd_draft').slice(-1)[0]||null;}
function intakeDraftText(item){
 const ai=intakeAiDraft(item);if(!ai)return '';
 const lines=[ai.job_description||''];
 if((ai.responsibilities||[]).length)lines.push('\nResponsibilities\n'+ai.responsibilities.map(x=>'• '+x).join('\n'));
 if((ai.required_qualifications||[]).length)lines.push('\nRequired Qualifications\n'+ai.required_qualifications.map(x=>'• '+x).join('\n'));
 if((ai.preferred_qualifications||[]).length)lines.push('\nPreferred Qualifications\n'+ai.preferred_qualifications.map(x=>'• '+x).join('\n'));
 if(ai.schedule_summary)lines.push('\nSchedule\n'+ai.schedule_summary);
 return lines.filter(Boolean).join('\n');
}
function renderIntakeItemReview(itemId){
 const item=activeIntakeItems.find(x=>x.id===itemId);if(!item)return;
 activeIntakeItem=item;const host=$('#intakeItemReview');if(!host)return;
 const j=item.normalized_job||{},sourceDescription=String(j.description||'').trim(),ai=intakeAiDraft(item);
 const draftText=ai?intakeDraftText(item):sourceDescription;
 const missing=item.missing_fields||[],conflicts=item.conflicts||[],warnings=ai?.warnings||[];
 host.innerHTML='<section class="intake-jd-review"><div class="intake-jd-head"><div><p class="eyebrow">JOB DESCRIPTION REVIEW</p><h3>'+esc(j.title||'Job')+'</h3><p class="admin-note">Source-confirmed facts stay separate from AI suggestions. Nothing is approved until you accept the reviewed JD.</p></div><div class="intake-jd-status"><span class="source-label">SOURCE FACTS</span>'+(ai?'<span class="ai-label">AI SUGGESTED</span>':'')+'</div></div>'+
 '<div class="intake-source-grid"><article><small>Facility</small><b>'+esc(j.facility||'Not provided')+'</b></article><article><small>Location</small><b>'+esc([j.city,j.state].filter(Boolean).join(', ')||'Not provided')+'</b></article><article><small>Assignment</small><b>'+esc([j.start_date,j.end_date].filter(Boolean).join(' → ')||'Dates pending')+'</b></article><article><small>Hours</small><b>'+(j.hours_per_week!=null?esc(j.hours_per_week)+' / week':'Not provided')+'</b></article><article><small>Bill Rate</small><b>'+(j.bill_rate!=null?'$'+esc(j.bill_rate):'Not provided')+'</b></article><article><small>Readiness</small><b>'+esc(String(item.recruiting_readiness||'review').replaceAll('_',' '))+'</b></article></div>'+
 (sourceDescription?'<div class="panel"><small>SOURCE JD / DESCRIPTION</small><p class="admin-note">'+esc(sourceDescription)+'</p></div>':'<div class="notice"><b>No usable source JD was provided.</b><br>Generate an AI draft from the confirmed job facts, then review and edit it before acceptance.</div>')+
 '<div class="ai-draft-box"><div><div><span class="ai-label">'+(ai?'AI DRAFT READY':'AI DRAFT NOT GENERATED')+'</span></div><button class="button" data-generate-intake-jd="'+esc(item.id)+'">'+(ai?'Regenerate AI Draft':'Generate AI Draft')+'</button></div>'+
 (ai?'<form id="intakeJdReviewForm" data-item-id="'+esc(item.id)+'"><label for="intakeJdText">Review and edit JD</label><textarea id="intakeJdText" maxlength="20000">'+esc(draftText)+'</textarea><p class="admin-note">Accepted text becomes Human Approved AI Draft provenance. It is not treated as customer-source-confirmed content.</p><div class="intake-review-actions"><button class="button primary" type="submit">Accept Reviewed JD</button></div></form>':'<p class="admin-note">AI will draft standard role content around the confirmed title, specialty, setting, location and assignment facts. Unknown customer-specific requirements remain unknown.</p>')+
 ((warnings.length||missing.length||conflicts.length)?'<div class="intake-warning-list">'+warnings.map(x=>'<span>AI warning: '+esc(x)+'</span>').join('')+missing.map(x=>'<span>Missing source fact: '+esc(x)+'</span>').join('')+conflicts.map(x=>'<span>Conflict: '+esc(x.message||x.code||x.field)+'</span>').join('')+'</div>':'')+'</div></section>';
}

