 if(form.id==='adminEditForm')return act(b,async()=>{const id=form.dataset.userId,role=$('#editRole').value,team=$('#editTeam').value,is_active=$('#editActive').value==='true';if(['manager','recruiter'].includes(role)&&!team)throw new Error('Choose a team for a recruiter or manager.');await write('adminedit:'+id,'/admin/users/'+id,{display_name:$('#editName').value.trim(),role,team_id:team||null,is_active},'PATCH');await drawAdmin(id);msg('User access settings updated and recorded in admin activity.','success');});
 if(form.id==='intakeUploadForm')return act(b,async()=>{const result=await uploadXlsx(form);activeIntake=result;await drawJobIntake();await loadIntakeBatch(result.id);msg('Spreadsheet processed. Review the flagged rows before approval.','success');});
 if(form.id==='intakeJdReviewForm')return act(b,async()=>{if(!activeIntake)throw new Error('Select an intake batch first.');const item=activeIntakeItems.find(x=>x.id===form.dataset.itemId);if(!item)throw new Error('Reload the intake batch and try again.');const description=$('#intakeJdText').value.trim();if(description.length<40)throw new Error('Review the AI draft and keep enough detail for a usable JD before accepting.');const finalValues={...(item.normalized_job||{}),description};await write('intake-decision:'+item.id,'/job-intake/batches/'+activeIntake.id+'/items/'+item.id+'/decision',{decision:'approved',final_approved_values:finalValues,bill_rate_state:item.bill_rate_state||'unknown',recruiting_readiness:item.recruiting_readiness||'review',commercial_readiness:item.commercial_readiness||'review',reason:'Manager reviewed and accepted the Job Intake JD'});await loadIntakeBatch(activeIntake.id);renderIntakeItemReview(item.id);msg('Reviewed JD accepted and sent to Job Approval.','success');});
 if(form.id==='weeklyGoalForm')return act(b,async()=>{weeklyWeek=$('#goalWeek').value;if(new Date(weeklyWeek+'T12:00:00').getDay()!==1)throw new Error('Choose a Monday as the week starting date.');await write('weeklygoal:'+session.member.id+':'+weeklyWeek,'/recruiters/'+session.member.id+'/weekly-goals',{week_start:weeklyWeek,submissions_target:Number($('#goalSubmissions').value),interviews_target:Number($('#goalInterviews').value),closures_target:Number($('#goalClosures').value),priority_jobs_target:Number($('#goalPriorityJobs').value),notes:$('#goalNotes').value.trim()||null},'PUT');await drawWeekly();msg('Monday goals committed. This baseline is now locked for the recruiter.','success');});
 if(form.id==='managerWeeklyGoalForm')return act(b,async()=>{const recruiterId=form.dataset.recruiterId;await write('weeklygoal-manager:'+recruiterId+':'+weeklyWeek,'/recruiters/'+recruiterId+'/weekly-goals',{week_start:weeklyWeek,submissions_target:Number($('#managerGoalSubmissions').value),interviews_target:Number($('#managerGoalInterviews').value),closures_target:Number($('#managerGoalClosures').value),priority_jobs_target:Number($('#managerGoalPriorityJobs').value),notes:$('#managerGoalNotes').value.trim()||null},'PUT');weeklyEditRecruiter=null;await drawWeekly();msg('Monday commitment adjusted by manager.','success');});
 if(!active)return;
